def integerBreak(n):
    if n < 4:
        return n - 1
    dp = [0] * (n + 1)
    dp[1], dp[2], dp[3] = 1, 2, 3
    for i in range(4, n + 1):
        dp[i] = max(3 * dp[i - 3], 2 * dp[i - 2])
    return dp[n]

